recipes.code:
{
  "inputs": [
    {
      "id": "agenttrust-api-key",
      "type": "promptString",
      "description": "Your AgentTrust API key from https://agenttrust.ai",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@agenttrust/mcp-server@1.1.1"
      ],
      "env": {
        "AGENTTRUST_API_KEY": "${input:agenttrust-api-key}"
      }
    }
  }
}
